import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI, Type } from "@google/genai";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const PORT = 3000;

app.use(express.json());

// API route for generating component files using Gemini AI
app.post("/api/gemini/generate-component", async (req, res) => {
  try {
    const { prompt, targetFolder } = req.body;
    if (!prompt || typeof prompt !== "string" || !prompt.trim()) {
      return res.status(400).json({ error: "Proporciona una descripción válida para el componente." });
    }

    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      return res.status(500).json({ error: "GEMINI_API_KEY no encontrada en la configuración del servidor." });
    }

    const ai = new GoogleGenAI({
      apiKey,
      httpOptions: {
        headers: {
          "User-Agent": "aistudio-build",
        },
      },
    });

    const systemInstruction = `Eres un desarrollador web frontend senior especializado en PWA instalables (HTML5, CSS3 moderno, JavaScript ES6+).
El usuario te dará una descripción de un componente o módulo web (ej: "un formulario de contacto con validación", "una calculadora de IMC", "un acordeón de preguntas frecuentes", "un conversor de moneda").
Debes generar los archivos necesarios para la solución funcional (HTML, CSS y JS, o archivos estructurados).
Asegúrate de que los enlaces entre HTML, CSS y JS usen rutas relativas coherentes.
Si el usuario especificó una carpeta (ej: "components/contact"), las rutas de los archivos generados deben empezar con esa carpeta (ej: "components/contact/index.html", "components/contact/style.css", "components/contact/script.js").
El código debe ser totalmente limpio, responsivo, estilizado con CSS moderno y listo para ser usado directamente en el explorador de archivos PWA.`;

    const userPrompt = `Genera los archivos estructurados (HTML, CSS, JavaScript) para el siguiente componente web PWA:
Descripción: "${prompt.trim()}"
${targetFolder ? `Carpeta destino solicitada: "${targetFolder.trim()}"` : "Si no hay carpeta especificada, crea los archivos en una subcarpeta limpia bajo components/ o en la ubicación más lógica."}`;

    const response = await ai.models.generateContent({
      model: "gemini-3.6-flash",
      contents: userPrompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            componentName: { type: Type.STRING, description: "Nombre descriptivo del componente" },
            files: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  path: { type: Type.STRING, description: "Ruta del archivo (ej: components/contact-form/contact.html)" },
                  content: { type: Type.STRING, description: "Código ejecutable completo para este archivo" }
                },
                required: ["path", "content"]
              }
            }
          },
          required: ["componentName", "files"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("Respuesta vacía del modelo Gemini.");
    }

    const result = JSON.parse(text);
    return res.json(result);
  } catch (error: any) {
    console.error("Error en /api/gemini/generate-component:", error);
    return res.status(500).json({ error: error?.message || "Error al procesar la solicitud con la IA Gemini." });
  }
});

// Vite middleware configuration for development vs production
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server listening on http://0.0.0.0:${PORT}`);
  });
}

startServer();
